    98	func proxyRaw(t *ProxyTarget, c echo.Context) http.Handler {
    99		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   100			in, _, err := c.Response().Hijack()
   101			if err != nil {
   102				c.Set("_error", fmt.Sprintf("proxy raw, hijack error=%v, url=%s", t.URL, err))
   103				return
   104			}
   105			defer in.Close()
   106	
   107			out, err := net.Dial("tcp", t.URL.Host)
   108			if err != nil {
   109				c.Set("_error", echo.NewHTTPError(http.StatusBadGateway, fmt.Sprintf("proxy raw, dial error=%v, url=%s", t.URL, err)))
   110				return
   111			}
   112			defer out.Close()
   113	
   114			// Write header
   115			err = r.Write(out)
   116			if err != nil {
   117				c.Set("_error", echo.NewHTTPError(http.StatusBadGateway, fmt.Sprintf("proxy raw, request header copy error=%v, url=%s", t.URL, err)))
   118				return
   119			}
   120	
   121			errCh := make(chan error, 2)
   122			cp := func(dst io.Writer, src io.Reader) {
   123				_, err = io.Copy(dst, src)
   124				errCh <- err
   125			}
   126	
   127			go cp(out, in)
   128			go cp(in, out)
   129			err = <-errCh
   130			if err != nil && err != io.EOF {
   131				c.Set("_error", fmt.Errorf("proxy raw, copy body error=%v, url=%s", t.URL, err))
   132			}
   133		})
   134	}
