357		// For example if there is no static node match we should check parent next sibling by kind (param).
358		// Backtracking itself does not check if there is a next sibling, this is done by the router logic.
359		backtrackToNextNodeKind := func(fromKind kind) (nextNodeKind kind, valid bool) {
360			previous := currentNode
361			currentNode = previous.parent
362			valid = currentNode != nil
