package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"
	"time"
)

func matchPattern(pattern, path string) bool {
	ps := strings.Split(pattern, "/")
	hs := strings.Split(path, "/")
	i := 0
	for ; i < len(ps); i++ {
		if i >= len(hs) {
			return false
		}
		if ps[i] == "*" {
			return i == len(ps)-1
		}
		if strings.HasPrefix(ps[i], ":") {
			if hs[i] == "" {
				return false
			}
			continue
		}
		if ps[i] != hs[i] {
			return false
		}
	}
	return i == len(hs)
}

func TestDiffRouter(t *testing.T) {
	segs := []string{"a", "b", "c", ":p", ":q", "*"}
	rand.Seed(42)
	checked := 0
	for iter := 0; iter < 30000; iter++ {
		n := 1 + rand.Intn(4)
		var routes []string
		for i := 0; i < n; i++ {
			m := 1 + rand.Intn(3)
			p := ""
			for j := 0; j < m; j++ {
				p += "/" + segs[rand.Intn(len(segs))]
			}
			routes = append(routes, p)
		}
		e := New()
		func() {
			defer func() {
				if r := recover(); r != nil {
					t.Fatalf("panic adding %v: %v", routes, r)
				}
			}()
			for _, p := range routes {
				e.Add(http.MethodGet, p, func(c Context) error { return nil })
			}
		}()
		for k := 0; k < 6; k++ {
			m := 1 + rand.Intn(4)
			path := ""
			for j := 0; j < m; j++ {
				path += "/" + segs[rand.Intn(len(segs))]
			}
			if strings.Contains(path, ":") || strings.Contains(path, "*") {
				continue
			}
			done := make(chan string, 1)
			go func() {
				defer func() {
					if r := recover(); r != nil {
						done <- fmt.Sprintf("panic: %v", r)
					}
				}()
				c := e.NewContext(nil, nil)
				e.router.Find(http.MethodGet, path, c)
				done <- ""
			}()
			var res string
			select {
			case res = <-done:
				if res != "" {
					t.Fatalf("routes %v path %s -> %s", routes, path, res)
				}
			case <-time.After(2 * time.Second):
				t.Fatalf("routes %v path %s -> hang", routes, path)
			}
			checked++
			c := e.NewContext(nil, nil)
			e.router.Find(http.MethodGet, path, c)
			matched := c.Path()
			if matched != "" {
				if !matchPattern(matched, path) {
					t.Fatalf("routes %v path %s -> matched pattern %q which does not match", routes, path, matched)
				}
			}
			// reverse: any registered pattern matching path should yield a match
			any := false
			for _, p := range routes {
				if matchPattern(p, path) {
					any = true
				}
			}
			if any && matched == "" {
				t.Fatalf("routes %v path %s -> no match but some pattern matches", routes, path)
			}
			if !any && matched != "" {
				t.Fatalf("routes %v path %s -> matched %q but no pattern matches", routes, path, matched)
			}
		}
	}
	t.Logf("checked %d", checked)
}
