	segs := []string{"a", "b", "c", ":p", ":q", "*"}
	rand.Seed(42)
	for iter := 0; iter < 30000; iter++ {
		n := 1 + rand.Intn(4)
		var routes []string
		for i := 0; i < n; i++ {
			m := 1 + rand.Intn(3)
			p := ""
			for j := 0; j < m; j++ {
				p += "/" + segs[rand.Intn(len(segs))]
			}
			routes = append(routes, p)
		}
		e := New()
		func() {
			defer func() {
				if r := recover(); r != nil {
					t.Fatalf("panic adding %v: %v", routes, r)
				}
			}()
			for _, p := range routes {
				e.Add(http.MethodGet, p, func(c Context) error { return nil })
			}
		}()
		for k := 0; k < 6; k++ {
			m := 1 + rand.Intn(4)
			path := ""
			for j := 0; j < m; j++ {
				path += "/" + segs[rand.Intn(len(segs))]
			}
			if strings.Contains(path, ":") || strings.Contains(path, "*") {
				continue
			}
			done := make(chan string, 1)
			go func() {
				defer func() {
					if r := recover(); r != nil {
						done <- fmt.Sprintf("panic: %v", r)
					}
				}()
				c := e.NewContext(nil, nil)
				e.router.Find(http.MethodGet, path, c)
				done <- ""
			}()
			select {
			case res := <-done:
				if res != "" {
					t.Fatalf("routes %v path %s -> %s", routes, path, res)
				}
			case <-time.After(2 * time.Second):
				t.Fatalf("routes %v path %s -> hang", routes, path)
			}
			c := e.NewContext(nil, nil)
			e.router.Find(http.MethodGet, path, c)
			matched := c.Path()
			registered := false
			for _, p := range routes {
				if p == matched {
					registered = true
				}
			}
			if !registered {
				continue
			}
			if !matchPattern(matched, path) {
				t.Fatalf("routes %v path %s -> matched pattern %q which does not match", routes, path, matched)
			}
		}
	}
}
